/// Register every pump.fun layout observed on mainnet.
///
/// Fails closed on the first row the registry refuses (a placeholder or a
/// duplicate key), so a corrupt table can never half-populate the gate.
pub fn register_observed_pumpfun_layouts(registry: &mut LayoutRegistry) -> Result<(), LayoutError> {
    for &(is_buy, cashback, token_2022, account_count, verifying_slot, verifying_signature) in
        PUMPFUN_OBSERVED
    {
        registry.record_verified(VerifiedLayout {
            key: LayoutKey {
                venue: Venue::PumpFun,
                side: if is_buy { Side::Buy } else { Side::Sell },
                variant: Variant {
                    cashback,
                    token_2022,
                    non_sol_quote: false,
                    reversed_pool: false,
                },
            },
            account_count,
            verifying_slot,
            verifying_signature,
        })?;
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The generated table must be self-consistent AND acceptable to the gate.
    /// This is the guard for the generator: re-running it against a bad probe
    /// (or against a probe whose field names changed) fails HERE rather than
    /// silently widening or bricking the §41 gate.
    #[test]
    fn observed_table_registers_and_matches_the_chain() {
        let mut reg = LayoutRegistry::new();
        register_observed_pumpfun_layouts(&mut reg).expect("every observed row must register");
        assert_eq!(
            reg.verified().len(),
            PUMPFUN_OBSERVED.len(),
            "no row may silently replace another"
        );

        for &(is_buy, _cashback, _t22, count, slot, sig) in PUMPFUN_OBSERVED {
            assert!(
                is_plausible_signature(&sig),
                "observed rows must carry real signatures, not placeholders"
            );
            assert!(
                slot > 400_000_000,
                "verifying slot must look like a real mainnet slot"
            );
            if is_buy {
                assert_eq!(
                    count, 18,
                    "a mainnet pump.fun buy is 18 accounts — never 17"
                );
            } else {
                assert!(
                    count == 16 || count == 17,
                    "a mainnet pump.fun sell is 16 or 17"
                );
            }
        }

        // The gate must refuse the 17-account BUY that the daemon used to register
        // by hand: no mainnet transaction has ever shown that layout.
        let buy = LayoutKey {
            venue: Venue::PumpFun,
            side: Side::Buy,
            variant: Variant {
                cashback: false,
                token_2022: true,
                non_sol_quote: false,
                reversed_pool: false,
            },
        };
        assert!(
            matches!(
                reg.require(&buy, 17),
                Err(LayoutError::CountDisagrees { .. })
            ),
            "a 17-account buy must NOT clear the gate"
        );
        assert!(
            reg.require(&buy, 18).is_ok(),
            "the observed 18-account buy must clear the gate"
        );
    }
}
